export const blogPosts: BlogPost[] = [...corePosts, ...clusterPosts].sort((a, b) =>
  a.publishedAt < b.publishedAt ? 1 : a.publishedAt > b.publishedAt ? -1 : 0,
);

export const getPost = (slug: string) => blogPosts.find((p) => p.slug === slug);
